begin;
insert into auth.users(id) values('a8888888-8888-4888-8888-888888888888'),('b8888888-8888-4888-8888-888888888888');
select set_config('request.jwt.claims','{"sub":"a8888888-8888-4888-8888-888888888888"}',true);
select public.kiyi_command('bundle');
update public.kiyi_wallets set balance=3000 where user_id='a8888888-8888-4888-8888-888888888888';
