set local role authenticated;
do $$declare c1 uuid;c2 uuid;b1 uuid;b2 uuid;x jsonb;ver int;rid uuid=gen_random_uuid();denied boolean;begin
 x=public.kiyi_command('vehicle_create','{"model":"peugeot-208","plate":"07 STG 301","paint":"#20242b"}');c1=(x->>'id')::uuid;
 x=public.kiyi_command('vehicle_create','{"model":"seat-leon","plate":"07 STG 302"}');c2=(x->>'id')::uuid;
 x=public.kiyi_command('vehicle_create','{"model":"honda-pcx-125","plate":"07 STG 303"}');b1=(x->>'id')::uuid;
 x=public.kiyi_command('vehicle_create','{"model":"yamaha-r25","plate":"07 STG 304"}');b2=(x->>'id')::uuid;
 x=public.kiyi_command('garage_list');assert (x->>'count')::int=4,'Wrong garage count';assert (select count(*) from jsonb_array_elements(x->'vehicles')g where g->>'kind'='car')=2,'Missing cars';assert (select count(*) from jsonb_array_elements(x->'vehicles')g where g->>'kind'='motorcycle')=2,'Missing motorcycles';
 denied=false;begin perform public.kiyi_command('vehicle_create','{"model":"seat-leon","plate":"07 STG 301"}');exception when unique_violation then denied=true;end;assert denied,'Duplicate plate accepted';
 perform public.kiyi_command('vehicle_update',jsonb_build_object('vehicle_id',c2,'plate','07 STG 305','visibility','public'));
 select (g->>'version')::int into ver from jsonb_array_elements(x->'vehicles')g where g->>'id'=b1::text;
 perform public.kiyi_command('motorcycle_customize',jsonb_build_object('vehicle_id',b1,'version',ver,'request_id',rid,'appearance','{"paint":"#ff0000","wrap":"carbon"}'::jsonb));
 perform public.kiyi_command('motorcycle_customize',jsonb_build_object('vehicle_id',b1,'version',ver,'request_id',rid,'appearance','{"paint":"#ff0000","wrap":"carbon"}'::jsonb));
 x=public.kiyi_command('bundle');assert (x->>'balance')::int=2300,'Wrong or duplicate debit';assert (x->'me'->>'vehicleCount')::int=4,'Wrong profile count';
 x=public.kiyi_command('garage_list');assert exists(select 1 from jsonb_array_elements(x->'vehicles')g where g->>'id'=b1::text and g->'appearance'->>'wrap'='carbon'),'Customization missing';assert exists(select 1 from jsonb_array_elements(x->'vehicles')g where g->>'id'=b2::text and not(g->'appearance'?'wrap')),'Customization leaked to second bike';
 perform public.kiyi_command('vehicle_primary',jsonb_build_object('vehicle_id',b1));x=public.kiyi_command('bundle');assert x->'me'->>'vehicleKind'='motorcycle','Wrong primary vehicle kind';
 perform public.kiyi_command('vehicle_delete',jsonb_build_object('vehicle_id',c2));x=public.kiyi_command('garage_list');assert (x->>'count')::int=3,'Deleted vehicle still listed';
 perform set_config('request.jwt.claims','{"sub":"b8888888-8888-4888-8888-888888888888"}',true);
 x=public.kiyi_command('garage_list');assert (x->>'count')::int=0,'Foreign vehicles leaked';
 denied=false;begin perform public.kiyi_command('vehicle_update',jsonb_build_object('vehicle_id',b1,'plate','07 STOLEN'));exception when insufficient_privilege then denied=true;end;assert denied,'Other user can update';
 denied=false;begin perform public.kiyi_command('vehicle_delete',jsonb_build_object('vehicle_id',b1));exception when insufficient_privilege then denied=true;end;assert denied,'Other user can delete';
 x=public.kiyi_command('garage_public','{"target":"a8888888-8888-4888-8888-888888888888"}');assert (x->>'count')::int=0,'Private garage leaked';
end$$;
