set local role authenticated;
do $$declare x jsonb;c uuid;b uuid;begin
 perform set_config('request.jwt.claims','{"sub":"a8888888-8888-4888-8888-888888888888"}',true);
 perform public.kiyi_command('profile','{"searchable":true}');
 x=public.kiyi_command('garage_list');
 select (g->>'id')::uuid into c from jsonb_array_elements(x->'vehicles')g where g->>'plate'='07 STG 301';
 select (g->>'id')::uuid into b from jsonb_array_elements(x->'vehicles')g where g->>'plate'='07 STG 303';
 perform public.kiyi_command('vehicle_update',jsonb_build_object('vehicle_id',c,'visibility','public'));
 perform public.kiyi_command('vehicle_update',jsonb_build_object('vehicle_id',b,'visibility','public'));
 perform public.kiyi_command('sharing','{"enabled":true}');
 perform public.kiyi_command('position',jsonb_build_object('session',gen_random_uuid(),'seq',1,'lat',36.86702735,'lng',30.6417432365968,'accuracy',10,'observed_at',(extract(epoch from clock_timestamp())*1000)::bigint));
 perform set_config('request.jwt.claims','{"sub":"b8888888-8888-4888-8888-888888888888"}',true);
 x=public.kiyi_command('garage_public','{"target":"a8888888-8888-4888-8888-888888888888"}');assert (x->>'count')::int=2,'Public garage unavailable';
 x=public.kiyi_command('directory','{"plate":"07stg301"}');assert jsonb_array_length(x->'profiles')=1,'Secondary plate search failed';assert x->'profiles'->0->>'plate'='07 STG 301','Wrong matched plate';
 x=public.kiyi_command('map','{"west":30.5,"east":30.8,"south":36.7,"north":37,"zoom":18,"region":"all","vehicle_kind":"motorcycle"}');assert jsonb_array_length(x->'people')=1,'Motorcycle map point missing';assert x->'people'->0->>'vehicleKind'='motorcycle','Wrong map kind';
 x=public.kiyi_command('map','{"west":30.5,"east":30.8,"south":36.7,"north":37,"zoom":18,"region":"all","vehicle_kind":"car"}');assert jsonb_array_length(x->'people')=0,'Car filter included motorcycle';
 perform set_config('request.jwt.claims','{"sub":"a8888888-8888-4888-8888-888888888888"}',true);
 perform public.kiyi_command('sharing','{"ghost":true}');
 perform set_config('request.jwt.claims','{"sub":"b8888888-8888-4888-8888-888888888888"}',true);
 x=public.kiyi_command('garage_public','{"target":"a8888888-8888-4888-8888-888888888888"}');assert (x->>'count')::int=0,'Ghost garage leaked';
 x=public.kiyi_command('map','{"west":30.5,"east":30.8,"south":36.7,"north":37,"zoom":18,"region":"all","vehicle_kind":"motorcycle"}');assert x->'people'->0->>'username'='hayalet','Ghost identity leaked';
end$$;
