 begin perform public.kiyi_command('motorcycle_customize',jsonb_build_object('vehicle_id',b,'version',ver,'request_id',gen_random_uuid(),'appearance','{"wrap":"stripe"}'::jsonb));exception when raise_exception then denied=SQLERRM='Yeterli kredi yok.';end;
 assert denied,'Insufficient balance did not reject purchase';
 x=public.kiyi_command('garage_list');assert exists(select 1 from jsonb_array_elements(x->'vehicles')g where g->>'id'=b::text and g->'appearance'->>'wrap'='carbon'),'Failed purchase changed appearance';
end$$;
